{
  "case_id": "C08",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook",
      "narration": "You've probably heard that your immune system 'remembers' an infection. That's true - but the way we usually picture it is only half right.",
      "on_screen": "Title card: 'Does your immune system really remember?' A cartoon filing cabinet fades in.",
      "claim_refs": ["SYN-C08:teaching_note:analogy"]
    },
    {
      "beat": "The filing cabinet",
      "narration": "The classic classroom picture is a filing cabinet. Your body meets a virus, keeps a folder on it, and pulls that folder out next time. After an infection clears, some virus-specific T cells really do stick around as a memory population.",
      "on_screen": "Cabinet drawer opens; a labelled folder slides out. Cut to illustrated T cells persisting in blood after a virus is cleared.",
      "claim_refs": ["SYN-C08:background", "SYN-C08:teaching_note:analogy"]
    },
    {
      "beat": "Where the analogy holds: speed",
      "narration": "Where the comparison works is speed. In this review of 302 adults, when people met the virus again, their memory response expanded 4.2 times faster than the first time round.",
      "on_screen": "Split timeline: slow first response versus a steep second curve. Caption: '4.2x faster secondary expansion (n=34, 95% CI 3.1-5.7)'.",
      "claim_refs": ["SYN-C08:results:secondary_expansion", "SYN-C08:stats:geometric_mean_ratio"]
    },
    {
      "beat": "Where it breaks: no index, and it fades",
      "narration": "But nothing is filed or indexed, and nothing is looked up on demand. And unlike paper in a drawer, these cells fade. Memory T cells for this virus were found in 88 percent of people at five years, but only 61 percent at twelve.",
      "on_screen": "Filing cabinet dissolves. Two bars: 88% at 5 years, 61% at 12 years, with confidence intervals 84-91 and 55-67.",
      "claim_refs": ["SYN-C08:results:5_years", "SYN-C08:results:12_years", "SYN-C08:teaching_note:note"]
    },
    {
      "beat": "The honest caveat",
      "narration": "One more thing: finding memory cells doesn't guarantee you won't get ill. And these numbers are for one virus target - persistence varies by pathogen and from person to person.",
      "on_screen": "Caption: 'Detectable memory does not equal protection.' Icons of different pathogens with varying bar heights.",
      "claim_refs": ["SYN-C08:teaching_note:note", "SYN-C08:limitations"]
    },
    {
      "beat": "Close",
      "narration": "So keep the filing cabinet for speed. Just remember the drawer slowly empties - which is exactly why booster schedules exist.",
      "on_screen": "Filing cabinet redrawn with a stopwatch on the front and a few folders thinning out. End card: 'Fast, not filed - and not forever.'",
      "claim_refs": ["SYN-C08:discussion", "SYN-C08:conclusion"]
    }
  ]
}
